// study-engine.js - LHS StudySpace Frontend Engine (Tailwind Styled)
let globalNotesIndex = [];
let currentSubject = "";

// 1. Fetch index map generated by Apps Script from GitHub
async function initStudyEngine() {
  try {
    const res = await fetch('notes/notes-index.json');
    globalNotesIndex = await res.json();
    console.log(`Study Engine loaded: ${globalNotesIndex.length} subtopics mapped.`);
  } catch (err) {
    console.error('Failed to load notes index:', err);
  }
}

// 2. Initialize Study Hub UI View
function loadStudyHub(containerId = 'studyHubContainer') {
  const container = document.getElementById(containerId);
  if (!container) return;

  if (!globalNotesIndex || !globalNotesIndex.length) {
    container.innerHTML = `
      <div class="p-8 text-center text-slate-500 dark:text-slate-400 text-xs font-semibold">
        No study notes loaded yet. Run <code class="text-emerald-500 font-mono">syncAllNotesToGitHub()</code> in Apps Script!
      </div>`;
    return;
  }

  // Get unique subjects dynamically
  const subjects = [...new Set(globalNotesIndex.map(n => n.subject))];

  let html = `
    <div class="space-y-4">
      <!-- Subject Navigation Tabs -->
      <div class="flex flex-wrap items-center gap-2 border-b border-slate-200 dark:border-slate-800 pb-3">
        ${subjects.map((sub, idx) => `
          <button 
            type="button"
            onclick="selectSubject('${sub}')" 
            class="tab-btn px-4 py-2 rounded-xl text-xs font-bold transition-all cursor-pointer ${idx === 0 ? 'bg-emerald-500 text-slate-950 shadow-md shadow-emerald-500/20' : 'bg-slate-100 dark:bg-slate-800/80 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700'}"
            data-subject="${sub}">
            ${sub}
          </button>
        `).join('')}
      </div>

      <!-- Subject Search Bar -->
      <div class="relative">
        <input 
          type="text" 
          id="subjectSearchInput" 
          placeholder="Search topics or keywords in this subject..." 
          oninput="handleSubjectSearch()"
          class="w-full px-4 py-2.5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl text-xs text-slate-900 dark:text-white placeholder-slate-400 dark:placeholder-slate-500 focus:ring-2 focus:ring-emerald-500 outline-none transition"
        />
      </div>

      <!-- Two-Column Grid Split -->
      <div class="grid grid-cols-1 lg:grid-cols-12 gap-5 min-h-[460px]">
        
        <!-- Left: Syllabus Sidebar -->
        <div id="syllabusView" class="lg:col-span-4 border-r border-slate-200 dark:border-slate-800 pr-3 space-y-4 max-h-[550px] overflow-y-auto">
        </div>
        
        <!-- Right: Note Reading Area -->
        <div id="noteReaderArea" class="lg:col-span-8 p-6 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl max-h-[550px] overflow-y-auto flex flex-col justify-center items-center">
          <div class="text-slate-400 dark:text-slate-500 text-xs italic text-center">
            👈 Select any subtopic on the left to read notes.
          </div>
        </div>

      </div>
    </div>
  `;

  container.innerHTML = html;
  if (subjects.length > 0) selectSubject(subjects[0]);
}

// 3. Select Subject & Highlight Active Tab
function selectSubject(subjectName) {
  currentSubject = subjectName;
  
  document.querySelectorAll('.tab-btn').forEach(btn => {
    const isSelected = btn.getAttribute('data-subject') === subjectName;
    if (isSelected) {
      btn.className = 'tab-btn px-4 py-2 rounded-xl text-xs font-extrabold bg-emerald-500 text-slate-950 shadow-md shadow-emerald-500/20 transition-all cursor-pointer';
    } else {
      btn.className = 'tab-btn px-4 py-2 rounded-xl text-xs font-bold bg-slate-100 dark:bg-slate-800/80 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700 transition-all cursor-pointer';
    }
  });

  const searchInput = document.getElementById('subjectSearchInput');
  if (searchInput) searchInput.value = "";

  renderSyllabusTree(globalNotesIndex.filter(n => n.subject === subjectName));
}

// 4. Render Units and Subtopics as Tailwind Cards
function renderSyllabusTree(notesList) {
  const view = document.getElementById('syllabusView');
  if (!view) return;

  if (!notesList.length) {
    view.innerHTML = `<div class="p-4 text-center text-xs text-slate-500">No matching subtopics found.</div>`;
    return;
  }

  // Group subtopics by Unit
  const units = {};
  notesList.forEach(item => {
    const unitName = item.unit || "General Unit";
    if (!units[unitName]) units[unitName] = [];
    units[unitName].push(item);
  });

  let html = `<div class="space-y-4">`;
  for (const [unitName, subtopics] of Object.entries(units)) {
    html += `
      <div class="space-y-2">
        <h4 class="text-[11px] font-extrabold uppercase tracking-wider text-emerald-600 dark:text-emerald-400 border-b border-slate-200 dark:border-slate-800/60 pb-1">
          ${unitName}
        </h4>
        <div class="space-y-1.5">
          ${subtopics.map(st => `
            <button 
              type="button"
              onclick="loadNoteContent('${st.filePath}')"
              class="w-full text-left p-2.5 rounded-xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 hover:border-emerald-500 dark:hover:border-emerald-500 text-xs font-medium text-slate-800 dark:text-slate-200 transition-all cursor-pointer flex items-center justify-between group">
              <span>${st.title}</span>
              <span class="text-slate-400 group-hover:text-emerald-500 transition-colors">&rarr;</span>
            </button>
          `).join('')}
        </div>
      </div>
    `;
  }
  html += `</div>`;
  view.innerHTML = html;
}

// 5. Search Engine Filtering
function handleSubjectSearch() {
  const query = document.getElementById('subjectSearchInput').value.toLowerCase().trim();
  
  if (!query) {
    renderSyllabusTree(globalNotesIndex.filter(n => n.subject === currentSubject));
    return;
  }

  const filtered = globalNotesIndex.filter(n => {
    if (n.subject !== currentSubject) return false;
    const matchTitle = n.title.toLowerCase().includes(query);
    const matchKeyword = n.keywords && n.keywords.some(k => k.toLowerCase().includes(query));
    return matchTitle || matchKeyword;
  });

  renderSyllabusTree(filtered);
}

// 6. Live Fetch Note Content
async function loadNoteContent(filePath) {
  const reader = document.getElementById('noteReaderArea');
  if (!reader) return;

  reader.innerHTML = `
    <div class="flex flex-col items-center justify-center py-12 gap-2 text-slate-500">
      <div class="w-7 h-7 border-3 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
      <span class="text-xs font-semibold">Loading note content...</span>
    </div>`;

  try {
    const res = await fetch(filePath);
    const html = await res.text();
    reader.className = "lg:col-span-8 p-6 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl max-h-[550px] overflow-y-auto text-xs leading-relaxed text-slate-800 dark:text-slate-200 space-y-3";
    reader.innerHTML = html;
  } catch (err) {
    reader.innerHTML = `<div class="text-xs text-rose-500 font-bold p-4">Error loading note content from GitHub.</div>`;
  }
}

document.addEventListener('DOMContentLoaded', initStudyEngine);
